#!/usr/bin/env python3
"""Read-only FCPXML dependency/time preflight; not a DTD or native import check."""
import argparse
from fractions import Fraction
import json
from pathlib import Path
import re
import sys
from urllib.parse import urlparse
from urllib.request import url2pathname
from xml.etree import ElementTree


def inspect(path):
    text = path.read_text(encoding="utf-8-sig")
    if re.search(r"<!ENTITY", text, re.IGNORECASE):
        raise ValueError("XML entity declarations are unsupported")
    root = ElementTree.fromstring(text)
    if root.tag != "fcpxml":
        raise ValueError("Expected an fcpxml root")
    errors = []
    resources = {}
    for element in root.findall("./resources/*"):
        identifier = element.get("id")
        if identifier:
            if identifier in resources:
                errors.append({"kind": "duplicate_resource", "id": identifier})
            resources[identifier] = element
    text_styles = {element.get("id") for element in root.iter("text-style-def") if element.get("id")}
    for element in root.iter():
        for name in ("ref", "format"):
            reference = element.get(name)
            definitions = text_styles if element.tag == "text-style" and name == "ref" else resources
            if reference and reference not in definitions:
                errors.append({"kind": "missing_resource", "tag": element.tag, "attribute": name, "ref": reference})
        for name in ("start", "offset", "duration", "frameDuration"):
            value = element.get(name)
            if value is None:
                continue
            try:
                if not re.fullmatch(r"-?\d+(?:/\d+)?s", value):
                    raise ValueError("Not an FCPXML rational time")
                time = Fraction(value[:-1])
                if name == "duration" and time < 0 or name == "frameDuration" and time <= 0:
                    raise ValueError("Invalid duration")
            except (ValueError, ZeroDivisionError):
                errors.append({"kind": "invalid_time", "tag": element.tag, "attribute": name, "value": value})
    media = []
    for asset in root.findall("./resources/asset"):
        sources = asset.findall("media-rep")
        if asset.get("src"):
            sources = [asset] + sources
        for source in sources:
            url = source.get("src", "")
            parsed = urlparse(url)
            local = bool(url) and parsed.scheme in ("", "file") and parsed.netloc in ("", "localhost")
            filename = Path(url2pathname(parsed.path)) if local else None
            if filename is not None and not filename.is_absolute():
                # Apple resolves relative media URLs against the FCPXML document.
                filename = path.parent / filename
            exists = filename.is_file() if filename is not None else None
            media.append({"asset": asset.get("id"), "kind": source.get("kind", "legacy"), "src": url, "exists": exists})
        if not sources:
            errors.append({"kind": "asset_without_source", "id": asset.get("id")})
    return {"file": str(path), "version": root.get("version"), "errors": errors, "media": media,
            "missing_media": [item for item in media if item["exists"] is False],
            "unchecked_media": [item for item in media if item["exists"] is None],
            "validation": "Dependency/time preflight only; native import and DTD validation remain required."}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("file", type=Path, help=".fcpxml, or .fcpxmld bundle containing Info.fcpxml")
    args = parser.parse_args()
    path = args.file.resolve()
    if path.is_dir():
        path = path / "Info.fcpxml"
    try:
        result = inspect(path)
    except (OSError, ValueError, ElementTree.ParseError) as error:
        print(json.dumps({"error": str(error)}))
        return 2
    print(json.dumps(result, indent=2))
    return 1 if result["errors"] or result["missing_media"] else 0


if __name__ == "__main__":
    sys.exit(main())
